/// The commitment ledger: every published pick, ascending, in the state its commitment is actually in. The counts are derived from entries in the same pass that builds it.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[non_exhaustive]
pub struct PickOfTheDayLedger {
    /// One entry per published (pick_date, pick_rank), ascending by pick_date then pick_rank.
    pub entries: Vec<PickOfTheDayLedgerEntry>,
    /// Number of entries, all states included.
    pub entry_count: i64,
    /// Entries committed to and not yet settled.
    pub sealed_count: i64,
    /// Entries committed to and verifiable now.
    pub opened_count: i64,
    /// Entries carrying no commitment, so provable by nothing: the honest size of the unprovable part of the record. It only stops growing; no pick is ever retro-sealed.
    pub uncommitted_count: i64,
}

/// One ledger entry. Read `state` to know which shape you have; the three are disjoint.
///
/// Discriminated by `state`. A `state` this release does not know is kept whole in
/// `Unknown`, so a new kind never fails a response.
#[derive(Debug, Clone, PartialEq)]
#[non_exhaustive]
pub enum PickOfTheDayLedgerEntry {
    /// `state` is `sealed`.
    Sealed(PickOfTheDayLedgerSealedEntry),
    /// `state` is `opened`.
    Opened(PickOfTheDayLedgerOpenedEntry),
    /// `state` is `uncommitted`.
    Uncommitted(PickOfTheDayLedgerUncommittedEntry),
    /// A `state` this release does not know, kept as sent.
    Unknown(serde_json::Value),
}

impl<'de> Deserialize<'de> for PickOfTheDayLedgerEntry {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        let value = serde_json::Value::deserialize(deserializer)?;
        match value.get("state").and_then(serde_json::Value::as_str) {
            Some("sealed") => serde_json::from_value(value)
                .map(Self::Sealed)
                .map_err(de::Error::custom),
            Some("opened") => serde_json::from_value(value)
                .map(Self::Opened)
                .map_err(de::Error::custom),
            Some("uncommitted") => serde_json::from_value(value)
                .map(Self::Uncommitted)
                .map_err(de::Error::custom),
            _ => Ok(Self::Unknown(value)),
        }
    }
}

impl Serialize for PickOfTheDayLedgerEntry {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        match self {
            Self::Sealed(inner) => inner.serialize(serializer),
            Self::Opened(inner) => inner.serialize(serializer),
            Self::Uncommitted(inner) => inner.serialize(serializer),
            Self::Unknown(inner) => inner.serialize(serializer),
        }
    }
}

